const h = require("fs").readFileSync(process.argv[2], "utf8");
const rows = [...h.matchAll(/<tr data-test="claim-row">(.*?)<\/tr>/g)]
  .map(m => [...m[1].matchAll(/<td[^>]*>(.*?)<\/td>/g)].map(x => x[1]));
const pence = s => Math.round(parseFloat(s) * 100);
const total = rows.reduce((s, r) => s + pence(r[3]), 0);
const byCat = {};
rows.forEach(r => (byCat[r[4]] = (byCat[r[4]] || 0) + pence(r[3])));
console.log("rows", rows.length, "total", (total / 100).toFixed(2));
for (const k in byCat) console.log(k, (byCat[k] / 100).toFixed(2));

